package ai.taskforge.domain;
import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="approvals",indexes=@Index(name="idx_approval_approver_status",columnList="approver_id,status")) public class Approval { @Id @GeneratedValue private UUID id; @ManyToOne(optional=false) @JoinColumn(name="task_id") private Task task; @ManyToOne(optional=false) @JoinColumn(name="requested_by_id") private AppUser requestedBy; @ManyToOne(optional=false) @JoinColumn(name="approver_id") private AppUser approver; @Enumerated(EnumType.STRING) @Column(nullable=false) private ApprovalStatus status=ApprovalStatus.PENDING; @Column(length=1000) private String comment; private Instant requestedAt=Instant.now(); private Instant decidedAt; protected Approval(){} public Approval(Task t,AppUser r,AppUser a,String c){task=t;requestedBy=r;approver=a;comment=c;} public UUID getId(){return id;} public Task getTask(){return task;} public AppUser getRequestedBy(){return requestedBy;} public AppUser getApprover(){return approver;} public ApprovalStatus getStatus(){return status;} public String getComment(){return comment;} public Instant getRequestedAt(){return requestedAt;} public void decide(ApprovalStatus s,String c){status=s;comment=c;decidedAt=Instant.now();} }
